function findByText(text) {
  const links = document.querySelectorAll('a');
  for (const link of links) {
    if (link.textContent.trim().includes(text)) {
      return link.href;
    }
  }
  return null;
}
return findByText('View 21 Spaces');

function findByText(text) {
  const links = document.querySelectorAll('a');
  const results = [];
  for (const link of links) {
    if (link.textContent.trim().includes(text)) {
      results.push({href: link.href, text: link.textContent.trim().substring(0, 100)});
    }
  }
  return results;
}
return findByText('Spaces');

const input = document.querySelector('input[type="search"][placeholder*="Filter"]');
if (input) {
  input.value = '';
  input.dispatchEvent(new Event('input', { bubbles: true }));
  input.dispatchEvent(new Event('change', { bubbles: true }));
  return 'cleared';
}
return 'not found';

async function checkSpace(repo) {
  const url = `https://huggingface.co/api/spaces/${repo}`;
  try {
    const response = await fetch(url);
    return {status: response.status, body: await response.text()};
  } catch(e) {
    return {error: e.message};
  }
}
const results = [];
for (const repo of ['argilla/notux-chat-ui', 'argilla/notux-chat', 'argilla/Notux-Chat-UI', 'argilla/notux', 'argilla/Notux-Chat', 'mrvero/Notux-Chat']) {
  results.push({repo, ...await checkSpace(repo)});
}
return results;

